<?php
declare(strict_types=1);
require_once __DIR__.'/config/finance_step16.php';
require_once __DIR__.'/config/security_step17.php';
$error=null;$m=['legacy'=>0,'products'=>0,'users'=>0,'sessions'=>0,'failed24'=>0,'journals'=>0,'cash_accounts'=>0,'receivable'=>0.0,'supplier_due'=>0.0,'stock'=>0.0];
try{
    $pdo=business_db();security_step17_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];
    $canFinance=security_step17_has_permission($pdo,'finance.view',$user);$canCustomers=security_step17_has_permission($pdo,'customers.view',$user);$canPurchases=security_step17_has_permission($pdo,'purchases.view',$user);$canInventory=security_step17_has_permission($pdo,'inventory.view',$user);$canSecurity=security_step17_has_permission($pdo,'security.audit.view',$user);$canAudit=security_step17_has_permission($pdo,'audit.view',$user);
    $s=$pdo->prepare("SELECT SUM(mapping_status='mapped') FROM raw_source_records WHERE organization_id=? AND source_dataset IN ('New UMS','Volume Points','First & Second Set','Active UMS Month_Wise','Renewal UMS','Monthely_Income','Royalty_Tracking','Extra Order for Customer')");$s->execute([$orgId]);$m['legacy']=(int)$s->fetchColumn();
    if(business_table_exists($pdo,'products')){$s=$pdo->prepare("SELECT COUNT(*) FROM products WHERE organization_id=? AND status='active'");$s->execute([$orgId]);$m['products']=(int)$s->fetchColumn();}
    if($canSecurity){$s=$pdo->prepare("SELECT COUNT(*) FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? WHERE u.is_active=1 AND a.is_active=1");$s->execute([$orgId]);$m['users']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM security_sessions WHERE organization_id=? AND revoked_at IS NULL AND expires_at>NOW()");$s->execute([$orgId]);$m['sessions']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM security_login_attempts WHERE organization_id=? AND was_successful=0 AND attempted_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR)");$s->execute([$orgId]);$m['failed24']=(int)$s->fetchColumn();}
    if($canFinance){finance_step16_ensure($pdo);finance_step16_sync_all($pdo);$s=$pdo->prepare("SELECT COUNT(*) FROM finance_journals WHERE organization_id=?");$s->execute([$orgId]);$m['journals']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM finance_cash_accounts WHERE organization_id=? AND status='active'");$s->execute([$orgId]);$m['cash_accounts']=(int)$s->fetchColumn();}
    if($canCustomers&&business_table_exists($pdo,'sales_fulfillment_ledger')){$s=$pdo->prepare("SELECT COALESCE(SUM(receivable_amount),0) FROM sales_fulfillment_ledger f JOIN product_sale_ledger sl ON sl.organization_id=f.organization_id AND sl.order_id=f.order_id WHERE f.organization_id=? AND sl.sale_status='active'");$s->execute([$orgId]);$m['receivable']=(float)$s->fetchColumn();}
    if($canPurchases&&business_table_exists($pdo,'purchase_bills')){foreach(purchase_step14_bill_rows($pdo,$orgId,'active') as $b){$st=purchase_step14_recalc_bill($pdo,$orgId,(int)$b['id']);$m['supplier_due']+=(float)$st['outstanding'];}}
    if($canInventory&&business_table_exists($pdo,'inventory_locations')){$loc=inventory_step13_location_id($pdo,$orgId);foreach(inventory_step13_stock_rows($pdo,$orgId,$loc) as $r)$m['stock']+=(float)$r['sellable_stock'];}
}catch(Throwable $e){$error=$e->getMessage();}
function d17m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}function d17n(mixed $v):string{$x=number_format((float)$v,3,'.','');return rtrim(rtrim($x,'0'),'.');}
